+  const hash = next.indexOf("#");
+  const query = next.indexOf("?");
+  const cuts = [hash, query].filter((i) => i >= 0);
+  if (cuts.length > 0) next = next.slice(0, Math.min(...cuts));
+  return next.trim();
+}
